// Extract key fields from the WhatsApp Cloud API payload
const entry   = $input.first().json.body.entry[0];
const change  = entry.changes[0].value;
const message = change.messages[0];
const contact = change.contacts[0];

return [{
  json: {
    sessionId:   message.from,           // phone number = unique session key
    senderPhone: message.from,
    senderName:  contact?.profile?.name ?? 'Customer',
    messageId:   message.id,
    messageText: message.text.body,
    timestamp:   message.timestamp,
    wabaId:      change.metadata.phone_number_id
  }
}];

// Parse the agent's reply and detect the qualification JSON block
const agentOutput = $input.first().json.output ?? '';

// Try to extract embedded JSON block
const jsonMatch = agentOutput.match(/```json\s*([\s\S]*?)```/);
let qualData = null;

if (jsonMatch) {
  try { qualData = JSON.parse(jsonMatch[1].trim()); } catch(e) {}
}

// Clean reply = agent text without the JSON block
const cleanReply = agentOutput.replace(/```json[\s\S]*?```/, '').trim();

// Determine routing
const isQualified = qualData?.qualified === true
  && typeof qualData?.budget_pkr === 'number'
  && typeof qualData?.timeline_months === 'number'
  && qualData.timeline_months <= 3;

return [{
  json: {
    ...($input.first().json),
    agentReply:      cleanReply,
    qualData:        qualData,
    isQualified:     isQualified,
    isColdLead:      qualData?.qualified === false
  }
}];

